1	package api
2	
3	// These regression cases exercise the storage-agnostic assembly entry
4	// NewRouterWithStore: the router is built from a caller-supplied
5	// service.Store — no Ping method, no SQLite, no database/sql — plus an
6	// independently provided health check. They pin the published behavior of
7	// POST/GET /v1/artifacts and GET /healthz on that boundary, including error
8	// priority and the mutual independence of the health check and the store.
9	
10	import (
11		"errors"
12		"net/http"
13		"net/http/httptest"
14		"path/filepath"
15		"testing"
16	
17		"github.com/gin-gonic/gin"
18	
19		"github.com/Bob-xisuke/orb-registry-catalog/internal/service"
20		"github.com/Bob-xisuke/orb-registry-catalog/internal/store"
21	)
22	
23	// testDigestC is a third valid digest for cross-entry scenarios; testDigestA
24	// and testDigestB come from artifacts_test.go.
25	const testDigestC = "sha256:" + "cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc"
26	
27	// assemblyStore is a caller-supplied service.Store written only against the
28	// exported storage contract. It keeps records in memory, can be forced to
29	// fail like any backend, and counts calls so tests can prove that rejected
30	// input never reaches storage.
31	type assemblyStore struct {
32		records []service.Record
33		byID    map[string]int               // repository\x00digest -> records index
34		tags    map[string]map[string]string // repository -> tag -> digest
35		fault   error
36		calls   map[string]int
37	}
38	
39	func newAssemblyStore() *assemblyStore {
40		return &assemblyStore{
41			byID:  make(map[string]int),
42			tags:  make(map[string]map[string]string),
43			calls: make(map[string]int),
44		}
45	}
46	
47	func assemblyID(repository, digest string) string { return repository + "\x00" + digest }
48	
49	func (a *assemblyStore) Register(in service.Record) (service.Record, service.RegisterStatus, error) {
50		a.calls["register"]++
51		if a.fault != nil {
52			return service.Record{}, 0, a.fault
53		}
54		key := assemblyID(in.Repository, in.Digest)
55		if idx, ok := a.byID[key]; ok {
56			existing := a.records[idx]
57			if existing.Tag == in.Tag &&
58				existing.SignatureVerified == in.SignatureVerified &&
59				existing.RetentionDays == in.RetentionDays &&
60				existing.SizeBytes == in.SizeBytes {
61				return existing, service.StatusDuplicate, nil
62			}
63			return service.Record{}, service.StatusConflict, nil
64		}
65		a.byID[key] = len(a.records)
66		a.records = append(a.records, in)
67		if a.tags[in.Repository] == nil {
68			a.tags[in.Repository] = make(map[string]string)
69		}
70		a.tags[in.Repository][in.Tag] = in.Digest
71		return in, service.StatusCreated, nil
72	}
73	
74	func (a *assemblyStore) ListRecords(repository string) ([]service.Record, error) {
75		a.calls["list"]++
76		if a.fault != nil {
77			return nil, a.fault
78		}
79		var out []service.Record
80		for _, record := range a.records {
81			if record.Repository == repository {
82				out = append(out, record)
83			}
84		}
85		return out, nil
86	}
87	
88	func (a *assemblyStore) RecordByDigest(repository, digest string) (service.Record, error) {
89		a.calls["digest"]++
90		if a.fault != nil {
91			return service.Record{}, a.fault
92		}
93		if idx, ok := a.byID[assemblyID(repository, digest)]; ok {
94			return a.records[idx], nil
95		}
96		return service.Record{}, service.ErrRecordNotFound
97	}
98	
99	func (a *assemblyStore) RecordByTag(repository, tag string) (service.Record, error) {
100		a.calls["tag"]++
101		if a.fault != nil {
102			return service.Record{}, a.fault
103		}
104		digest, ok := a.tags[repository][tag]
105		if !ok {
106			return service.Record{}, service.ErrRecordNotFound
107		}
108		return a.records[a.byID[assemblyID(repository, digest)]], nil
109	}
110	
111	func (a *assemblyStore) totalCalls() int {
112		total := 0
113		for _, n := range a.calls {
114			total += n
115		}
116		return total
117	}
118	
119	// assemblyProbe is a health check the test flips between requests; every
120	// /healthz call must consult it again.
121	type assemblyProbe struct {
122		err   error
123		calls int
124	}
125	
126	func (p *assemblyProbe) check() error {
127		p.calls++
128		return p.err
129	}
130	
131	func newAssemblyRouter(st *assemblyStore, probe *assemblyProbe) *gin.Engine {
132		return NewRouterWithStore(st, probe.check)
133	}
134	
135	func getHealth(t *testing.T, router *gin.Engine) *httptest.ResponseRecorder {
136		t.Helper()
137		recorder := httptest.NewRecorder()
138		router.ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, "/healthz", nil))
139		return recorder
140	}
141	
142	// TestAssemblyEntryRegisterAndQuery walks the full registration and query
143	// contract through the new entry on a caller-supplied store: first
144	// registration and identical retry share 201 and the original pushed_at, the
145	// tag pointer moves only on new content, conflicts are 409, lists keep
146	// first-registration order and misses are 404.
147	func TestAssemblyEntryRegisterAndQuery(t *testing.T) {
148		st := newAssemblyStore()
149		router := newAssemblyRouter(st, &assemblyProbe{})
150	
151		bodyA := registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)
152		bodyB := registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB)
153	
154		first := postArtifact(t, router, bodyA)
155		if first.Code != http.StatusCreated {
156			t.Fatalf("register A status = %d, want %d (%s)", first.Code, http.StatusCreated, first.Body)
157		}
158		pushedA, _ := decodeBody(t, first)["pushed_at"].(string)
159		if pushedA == "" {
160			t.Fatalf("A response has no pushed_at: %s", first.Body)
161		}
162	
163		second := postArtifact(t, router, bodyB)
164		if second.Code != http.StatusCreated {
165			t.Fatalf("register B status = %d, want %d (%s)", second.Code, http.StatusCreated, second.Body)
166		}
167		pushedB, _ := decodeBody(t, second)["pushed_at"].(string)
168	
169		// The tag pointer moved to B; A survives by digest.
170		if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestB {
171			t.Fatalf("tag after B points at %v, want %s", got["digest"], testDigestB)
172		}
173		expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestA)),
174			sequenceRepo, testDigestA, sequenceTag, true,
175			float64(regRetention), float64(regSizeA), pushedA)
176	
177		// Identical retry of A: 201 with the original pushed_at, no new record and
178		// the tag pointer does not move back.
179		retry := postArtifact(t, router, bodyA)
180		if retry.Code != http.StatusCreated {
181			t.Fatalf("retry A status = %d, want %d (%s)", retry.Code, http.StatusCreated, retry.Body)
182		}
183		if got := decodeBody(t, retry)["pushed_at"]; got != pushedA {
184			t.Fatalf("retry pushed_at = %v, want original %v", got, pushedA)
185		}
186		if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestB {
187			t.Fatalf("retry moved the tag pointer: %v", got)
188		}
189		if digests := recordDigests(allRecords(t, queryList(t, router, sequenceRepo))); len(digests) != 2 ||
190			digests[0] != testDigestA || digests[1] != testDigestB {
191			t.Fatalf("list = %v, want [%s %s] in registration order", digests, testDigestA, testDigestB)
192		}
193	
194		// Same identity with different content: 409, and nothing changes.
195		conflict := postArtifact(t, router,
196			registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeB))
197		assertErrorResponse(t, conflict, http.StatusConflict, codeConflict, msgConflict)
198		expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestA)),
199			sequenceRepo, testDigestA, sequenceTag, true,
200			float64(regRetention), float64(regSizeA), pushedA)
201		if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["pushed_at"] != pushedB {
202			t.Fatalf("tagged record changed after conflict: %v", got)
203		}
204	
205		// Legal queries with no match are 404.
206		assertErrorResponse(t, queryList(t, router, "registry-demo/missing"),
207			http.StatusNotFound, codeNotFound, msgNotFound)
208		assertErrorResponse(t, queryByTag(t, router, sequenceRepo, "missing-tag"),
209			http.StatusNotFound, codeNotFound, msgNotFound)
210		assertErrorResponse(t, queryByDigest(t, router, sequenceRepo, testDigestB[:len(testDigestB)-1]+"c"),
211			http.StatusNotFound, codeNotFound, msgNotFound)
212	}
