11		digestB = "sha256:" + "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
12	)
13	
14	// newTestService builds a Service over the in-memory fake, so the business
15	// rules below are verified without opening SQLite or any database handle.
16	func newTestService() (*Service, *fakeStore) {
17		st := newFakeStore()
18		return New(st), st
19	}
20	
21	func validInput(repo, digest, tag string) RegisterInput {
22		return RegisterInput{
23			Repository:        repo,
24			Digest:            digest,
25			Tag:               tag,
26			SignatureVerified: true,
27			RetentionDays:     30,
28			SizeBytes:         1024,
29		}
30	}
31	
32	func wantRecord(t *testing.T, got Artifact, in RegisterInput, pushedAt string) {
33		t.Helper()
34		want := Artifact{
35			Repository:        in.Repository,
36			Digest:            in.Digest,
37			Tag:               in.Tag,
38			SignatureVerified: in.SignatureVerified,
39			RetentionDays:     in.RetentionDays,
40			SizeBytes:         in.SizeBytes,
41			PushedAt:          pushedAt,
42		}
43		if got != want {
44			t.Fatalf("record = %+v, want %+v", got, want)
45		}
46	}
47	
48	func assertRFC3339UTC(t *testing.T, value string) {
49		t.Helper()
50		parsed, err := time.Parse(time.RFC3339, value)
51		if err != nil {
52			t.Fatalf("pushed_at %q is not RFC3339: %v", value, err)
53		}
54		if parsed.Location() != time.UTC {
55			t.Fatalf("pushed_at %q is not UTC", value)
56		}
57	}
58	
59	func TestRegisterCreatedThenDuplicate(t *testing.T) {
60		svc, st := newTestService()
61		input := validInput("team/app", digestA, "latest")
62	
63		first, err := svc.Register(input)
64		if err != nil {
65			t.Fatalf("first register: %v", err)
66		}
67		if first.Outcome != OutcomeCreated {
68			t.Fatalf("first outcome = %v, want OutcomeCreated", first.Outcome)
69		}
70		assertRFC3339UTC(t, first.Artifact.PushedAt)
71		wantRecord(t, first.Artifact, input, first.Artifact.PushedAt)
72		pushedAt := first.Artifact.PushedAt
73	
74		// The first registration wrote exactly one record and moved its tag.
75		if len(st.records) != 1 {
76			t.Fatalf("records after first register = %d, want 1", len(st.records))
77		}
78	
79		// An identical retry is distinguishable as a duplicate and returns the
80		// original record, including its push time.
81		second, err := svc.Register(input)
82		if err != nil {
83			t.Fatalf("duplicate register: %v", err)
84		}
85		if second.Outcome != OutcomeDuplicate {
86			t.Fatalf("duplicate outcome = %v, want OutcomeDuplicate", second.Outcome)
87		}
88		if second.Artifact != first.Artifact {
89			t.Fatalf("duplicate record = %+v, want original %+v", second.Artifact, first.Artifact)
90		}
91		if second.Artifact.PushedAt != pushedAt {
92			t.Fatalf("pushed_at changed on duplicate: %q -> %q", pushedAt, second.Artifact.PushedAt)
93		}
94		if len(st.records) != 1 {
95			t.Fatalf("duplicate register added a record: now %d, want 1", len(st.records))
96		}
97	}
98	
99	func TestRegisterConflictLeavesRecordAndTagUntouched(t *testing.T) {
100		svc, _ := newTestService()
101		input := validInput("team/app", digestA, "latest")
102	
103		first, err := svc.Register(input)
104		if err != nil {
105			t.Fatalf("first register: %v", err)
106		}
107	
108		// Move the tag to B so we can prove a rejected re-registration of A never
109		// moves it back.
110		inputB := validInput("team/app", digestB, "latest")
111		inputB.SizeBytes = 2048
112		if _, err := svc.Register(inputB); err != nil {
113			t.Fatalf("register B: %v", err)
114		}
115	
116		conflicts := map[string]RegisterInput{
117			"changed tag":       withChanges(input, func(in *RegisterInput) { in.Tag = "other" }),
118			"changed signature": withChanges(input, func(in *RegisterInput) { in.SignatureVerified = false }),
119			"changed retention": withChanges(input, func(in *RegisterInput) { in.RetentionDays = 31 }),
120			"changed size":      withChanges(input, func(in *RegisterInput) { in.SizeBytes = 2048 }),
121		}
122		for name, bad := range conflicts {
123			t.Run(name, func(t *testing.T) {
124				if _, err := svc.Register(bad); !errors.Is(err, ErrConflict) {
125					t.Fatalf("register error = %v, want ErrConflict", err)
126				}
127	
128				// The immutable A record is unchanged, including pushed_at.
129				byDigest, err := svc.Query(Query{Kind: QueryByDigest, Repository: "team/app", Digest: digestA})
130				if err != nil {
131					t.Fatalf("query A after conflict: %v", err)
132				}
133				if len(byDigest) != 1 || byDigest[0] != first.Artifact {
134					t.Fatalf("A record changed after conflict: %+v", byDigest)
135				}
136	
137				// The tag still resolves to B.
138				byTag, err := svc.Query(Query{Kind: QueryByTag, Repository: "team/app", Tag: "latest"})
139				if err != nil {
140					t.Fatalf("query tag after conflict: %v", err)
141				}
142				if len(byTag) != 1 || byTag[0].Digest != digestB {
143					t.Fatalf("tag pointer moved after conflict: %+v", byTag)
144				}
145	
146				// No third record and registration order is intact.
147				list, err := svc.Query(Query{Kind: QueryByRepository, Repository: "team/app"})
148				if err != nil {
149					t.Fatalf("list after conflict: %v", err)
150				}
151				if len(list) != 2 || list[0].Digest != digestA || list[1].Digest != digestB {
152					t.Fatalf("list changed after conflict: %+v", list)
153				}
154	
155				// The rejected body's tag was never persisted.
156				if _, err := svc.Query(Query{Kind: QueryByTag, Repository: "team/app", Tag: "other"}); !errors.Is(err, ErrNotFound) {
157					t.Fatalf("rejected tag lookup error = %v, want ErrNotFound", err)
158				}
159			})
160		}
161	}
162	
163	func withChanges(in RegisterInput, change func(*RegisterInput)) RegisterInput {
164		change(&in)
165		return in
166	}
